function DatePicker({value,onChange,label}:{value:string;onChange:(value:string)=>void;label:string}) {
 const parse=(date:string)=>new Date(`${date}T12:00:00.000Z`);
 const [open,setOpen]=useState(false),[view,setView]=useState(()=>parse(value));
 useEffect(()=>setView(parse(value)),[value]);
 const first=new Date(Date.UTC(view.getUTCFullYear(),view.getUTCMonth(),1)),offset=(first.getUTCDay()+6)%7;
 const days=Array.from({length:42},(_,i)=>new Date(Date.UTC(view.getUTCFullYear(),view.getUTCMonth(),1+(i-offset))));
 const month=new Intl.DateTimeFormat("es-AR",{month:"long",year:"numeric",timeZone:"UTC"}).format(view);
 const selected=parse(value).toISOString().slice(0,10),today=dateLocal();
 const display=new Intl.DateTimeFormat("es-AR",{day:"numeric",month:"short",year:"numeric",timeZone:"UTC"}).format(parse(value));
 const shiftMonth=(amount:number)=>setView(current=>new Date(Date.UTC(current.getUTCFullYear(),current.getUTCMonth()+amount,1)));
 return <div className="date-picker"><span className="date-picker-label">{label}</span><button type="button" className="date-picker-trigger" aria-expanded={open} onClick={()=>setOpen(!open)}><span className="date-picker-icon">▦</span><span>{display}</span><span className="date-picker-chevron">⌄</span></button>{open&&<div className="date-picker-popover"><div className="calendar-heading"><button type="button" aria-label="Mes anterior" onClick={()=>shiftMonth(-1)}>‹</button><b>{month}</b><button type="button" aria-label="Mes siguiente" onClick={()=>shiftMonth(1)}>›</button></div><div className="calendar-grid calendar-weekdays">{["Lu","Ma","Mi","Ju","Vi","Sa","Do"].map(day=><span key={day}>{day}</span>)}</div><div className="calendar-grid">{days.map(day=>{const key=day.toISOString().slice(0,10),inMonth=day.getUTCMonth()===view.getUTCMonth();return <button type="button" key={key} className={`calendar-day ${!inMonth?"calendar-day-muted":""} ${key===selected?"calendar-day-selected":""} ${key===today?"calendar-day-today":""}`} onClick={()=>{onChange(key);setOpen(false);}}>{day.getUTCDate()}</button>})}</div><button type="button" className="calendar-today" onClick={()=>{onChange(today);setView(parse(today));setOpen(false);}}>Ir a hoy</button></div>}</div>;
}
